begin;
do $$begin
 if to_regprocedure('public.erp_table_read(text,text,jsonb,text,text,integer,text)') is null then raise exception 'Apply migrations 001–017 before 018.';end if;
end $$;
-- Retain the existing location IDs and textual warehouse labels.
create table if not exists public.erp_warehouses(
 id uuid primary key default gen_random_uuid(),code text unique not null check(length(btrim(code)) between 1 and 30),name text unique not null check(length(btrim(name)) between 1 and 100),address text not null default '',active boolean not null default true,version integer not null default 1);
alter table public.erp_locations add column if not exists warehouse_id uuid references public.erp_warehouses(id);
alter table public.erp_locations add column if not exists bin text not null default '';
alter table public.erp_locations add column if not exists active boolean not null default true;
insert into public.erp_warehouses(code,name) select 'WH-'||row_number() over(order by warehouse),warehouse from (select distinct warehouse from public.erp_locations where warehouse_id is null) w on conflict(name) do nothing;
update public.erp_locations l set warehouse_id=w.id from public.erp_warehouses w where l.warehouse_id is null and w.name=l.warehouse;
alter table public.erp_locations alter column warehouse_id set not null;
create table if not exists public.erp_warehouse_access(user_id uuid references public.users(id) on delete cascade,warehouse_id uuid references public.erp_warehouses(id),can_read boolean not null default true,can_write boolean not null default false,can_approve boolean not null default false,primary key(user_id,warehouse_id),check(can_read or not(can_write or can_approve)));
-- An explicit scope turns off implicit all-warehouse access for this user.
create table if not exists public.erp_warehouse_scopes(user_id uuid primary key references public.users(id) on delete cascade,restricted boolean not null default true);
create table if not exists public.erp_work_requests(request_key uuid primary key,actor_id uuid not null references public.users(id),action text not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default now());
create table if not exists public.erp_work_events(id bigint generated always as identity primary key,entity text not null,record_id uuid not null,action text not null,actor_id uuid not null references public.users(id),reason text not null default '',before_data jsonb not null default '{}',after_data jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists erp_work_events_record on public.erp_work_events(entity,record_id,id desc);
alter table public.erp_material_transactions add column if not exists managed_by_workflow boolean not null default false;
-- Old material inventory stays explicitly historical, never backfilled with a fictitious PASS.
alter table public.erp_materials add column if not exists requires_qc boolean not null default false;
alter table public.erp_materials add column if not exists requires_approved_supplier boolean not null default false;
alter table public.erp_materials alter column requires_qc set default false;
alter table public.erp_materials alter column requires_approved_supplier set default false;


alter table public.erp_material_lots add column if not exists quality_status text not null default 'legacy' check(quality_status in ('legacy','quarantine','released','rejected','disposed'));
alter table public.erp_material_lots alter column quality_status set default 'quarantine';
create table if not exists public.erp_approved_suppliers(id uuid primary key default gen_random_uuid(),material_id uuid not null references public.erp_materials(id),supplier_id uuid not null references public.erp_suppliers(id),effective_date date not null,expiry_date date,state text not null default 'draft' check(state in ('draft','approved','withdrawn')),reason text not null default '',created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,check(expiry_date is null or expiry_date>=effective_date));
create unique index if not exists erp_supplier_qualification_current on public.erp_approved_suppliers(material_id,supplier_id) where state='approved';
create table if not exists public.erp_material_specs(id uuid primary key default gen_random_uuid(),root_id uuid not null,material_id uuid not null references public.erp_materials(id),revision integer not null check(revision>0),title text not null,parameters jsonb not null check(jsonb_typeof(parameters)='array'),effective_date date not null,state text not null default 'draft' check(state in ('draft','approved','superseded','withdrawn')),created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,unique(material_id,revision));
create unique index if not exists erp_material_spec_current on public.erp_material_specs(material_id) where state='approved';
create table if not exists public.erp_incoming_inspections(id uuid primary key default gen_random_uuid(),number text unique not null,lot_id uuid not null references public.erp_material_lots(id),receipt_id uuid references public.erp_material_transactions(id),spec_id uuid not null references public.erp_material_specs(id),spec_snapshot jsonb not null,date date not null,results jsonb not null default '[]',state text not null default 'draft' check(state in ('draft','pass','fail','withdrawn')),failure_reason text not null default '',previous_id uuid references public.erp_incoming_inspections(id),created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,created_at timestamptz not null default now());
alter table public.erp_material_lots add column if not exists inspection_id uuid references public.erp_incoming_inspections(id);
create table if not exists public.erp_controlled_documents(id uuid primary key default gen_random_uuid(),number text unique not null,root_id uuid not null,material_id uuid references public.erp_materials(id),supplier_id uuid references public.erp_suppliers(id),title text not null,kind text not null,language text not null check(language in ('en','id')),revision integer not null check(revision>0),file_url text not null check(file_url ~ '^https://[^[:space:]]+$'),effective_date date not null,expiry_date date,state text not null default 'draft' check(state in ('draft','published','superseded','withdrawn')),created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,check(num_nonnulls(material_id,supplier_id)=1),check(expiry_date is null or expiry_date>=effective_date),unique(root_id,revision));
create unique index if not exists erp_controlled_doc_current on public.erp_controlled_documents(root_id) where state='published';
create table if not exists public.erp_formulas(id uuid primary key default gen_random_uuid(),number text unique not null,root_id uuid not null,product_id uuid not null references public.master_produk(id),revision integer not null check(revision>0),title text not null,output_quantity numeric(24,6) not null check(output_quantity>0),unit_id uuid not null references public.erp_units(id),lines jsonb not null check(jsonb_typeof(lines)='array' and jsonb_array_length(lines) between 1 and 100),effective_date date not null,state text not null default 'draft' check(state in ('draft','approved','superseded','withdrawn')),notes text not null default '',created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,unique(root_id,revision));
create unique index if not exists erp_formula_current on public.erp_formulas(root_id) where state='approved';
create table if not exists public.erp_manufacturing_orders(id uuid primary key default gen_random_uuid(),number text unique not null,formula_id uuid not null references public.erp_formulas(id),formula_snapshot jsonb not null,product_id uuid not null references public.master_produk(id),target_quantity numeric(24,6) not null check(target_quantity>0),unit_id uuid not null references public.erp_units(id),planned_date date not null,location_id uuid not null references public.erp_locations(id),state text not null default 'draft' check(state in ('draft','released','in_progress','completed','closed','cancelled')),sales_order_id uuid references public.erp_orders(id),scrap_quantity numeric(24,6) not null default 0 check(scrap_quantity>=0),notes text not null default '',closure_reason text,created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.erp_material_reservations(id uuid primary key default gen_random_uuid(),manufacturing_order_id uuid not null references public.erp_manufacturing_orders(id),material_id uuid not null references public.erp_materials(id),lot_id uuid not null references public.erp_material_lots(id),location_id uuid not null references public.erp_locations(id),quantity numeric(24,6) not null check(quantity>0),remaining numeric(24,6) not null check(remaining>=0 and remaining<=quantity),state text not null default 'active' check(state in ('active','consumed','released')),created_at timestamptz not null default now());
create index if not exists erp_material_reserved on public.erp_material_reservations(lot_id,location_id) where state='active';
create table if not exists public.erp_manufacturing_inputs(id uuid primary key default gen_random_uuid(),manufacturing_order_id uuid not null references public.erp_manufacturing_orders(id),reservation_id uuid references public.erp_material_reservations(id),transaction_id uuid unique not null references public.erp_material_transactions(id),lot_id uuid not null references public.erp_material_lots(id),location_id uuid not null references public.erp_locations(id),quantity numeric(24,6) not null check(quantity>0),kind text not null check(kind in ('consume','return')),returns_id uuid references public.erp_manufacturing_inputs(id),measured_by uuid not null references public.users(id),reason text not null,created_at timestamptz not null default now(),check((kind='return')=(returns_id is not null)));
create table if not exists public.erp_manufacturing_outputs(id uuid primary key default gen_random_uuid(),manufacturing_order_id uuid not null references public.erp_manufacturing_orders(id),movement_id uuid unique not null references public.erp_movements(id),lot_id uuid not null references public.erp_lots(id),quantity numeric(24,6) not null check(quantity>0),created_at timestamptz not null default now());
create index if not exists erp_mo_inputs_trace on public.erp_manufacturing_inputs(lot_id,manufacturing_order_id);
create index if not exists erp_mo_outputs_trace on public.erp_manufacturing_outputs(lot_id,manufacturing_order_id);
create table if not exists public.erp_deviations(id uuid primary key default gen_random_uuid(),number text unique not null,material_lot_id uuid references public.erp_material_lots(id),manufacturing_order_id uuid references public.erp_manufacturing_orders(id),inspection_id uuid references public.erp_incoming_inspections(id),title text not null,description text not null,investigation text not null default '',disposition text not null default '',state text not null default 'open' check(state in ('open','investigating','awaiting_approval','approved','closed','rejected')),assignee uuid references public.users(id),due_date date not null,created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1,created_at timestamptz not null default now(),check(num_nonnulls(material_lot_id,manufacturing_order_id,inspection_id)>=1));
create table if not exists public.erp_capas(id uuid primary key default gen_random_uuid(),number text unique not null,deviation_id uuid not null references public.erp_deviations(id),title text not null,kind text not null check(kind in ('corrective','preventive')),action text not null,assignee uuid not null references public.users(id),due_date date not null,state text not null default 'open' check(state in ('open','in_progress','awaiting_review','verified','cancelled')),evidence text not null default '',effectiveness text not null default '',created_by uuid not null references public.users(id),approved_by uuid references public.users(id),version integer not null default 1);
create table if not exists public.erp_warehouse_transfers(id uuid primary key default gen_random_uuid(),number text unique not null,from_location uuid not null references public.erp_locations(id),to_location uuid not null references public.erp_locations(id),date date not null,state text not null default 'draft' check(state in ('draft','in_transit','partial','received','closed','cancelled')),reason text not null,created_by uuid not null references public.users(id),version integer not null default 1,created_at timestamptz not null default now(),check(from_location<>to_location));
create table if not exists public.erp_transfer_lines(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references public.erp_warehouse_transfers(id),kind text not null check(kind in ('material','finished')),material_lot_id uuid references public.erp_material_lots(id),lot_id uuid references public.erp_lots(id),quantity numeric(24,6) not null check(quantity>0),received numeric(24,6) not null default 0 check(received>=0),lost numeric(24,6) not null default 0 check(lost>=0),check((kind='material' and material_lot_id is not null and lot_id is null) or (kind='finished' and lot_id is not null and material_lot_id is null)),check(received+lost<=quantity));
create table if not exists public.erp_pallets(id uuid primary key default gen_random_uuid(),number text unique not null,location_id uuid references public.erp_locations(id),transfer_id uuid references public.erp_warehouse_transfers(id),state text not null default 'empty' check(state in ('empty','packed','in_transit','dispatched','retired')),notes text not null default '',created_by uuid not null references public.users(id),version integer not null default 1,created_at timestamptz not null default now(),check(state<>'in_transit' or transfer_id is not null));
create table if not exists public.erp_pallet_contents(id uuid primary key default gen_random_uuid(),pallet_id uuid not null references public.erp_pallets(id),kind text not null check(kind in ('material','finished')),material_lot_id uuid references public.erp_material_lots(id),lot_id uuid references public.erp_lots(id),quantity numeric(24,6) not null check(quantity>0),check((kind='material' and material_lot_id is not null and lot_id is null) or (kind='finished' and lot_id is not null and material_lot_id is null)));
create unique index if not exists erp_pallet_material_unique on public.erp_pallet_contents(pallet_id,material_lot_id) where kind='material';
create unique index if not exists erp_pallet_finished_unique on public.erp_pallet_contents(pallet_id,lot_id) where kind='finished';
alter table public.erp_transfer_lines add column if not exists pallet_id uuid references public.erp_pallets(id);
create table if not exists public.erp_sample_requests(id uuid primary key default gen_random_uuid(),number text unique not null,customer_id uuid not null references public.erp_customers(id),opportunity_id uuid references public.erp_opportunities(id),product_id uuid not null references public.master_produk(id),quantity numeric(24,6) not null check(quantity>0),unit_id uuid not null references public.erp_units(id),purpose text not null,state text not null default 'requested' check(state in ('requested','approved','prepared','shipped','feedback','converted','cancelled')),due_date date not null,assignee uuid references public.users(id),lot_id uuid references public.erp_lots(id),location_id uuid references public.erp_locations(id),movement_id uuid references public.erp_movements(id),tracking_reference text not null default '',feedback text not null default '',quote_id uuid references public.erp_quotes(id),created_by uuid not null references public.users(id),version integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.erp_customer_interactions(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.erp_customers(id),opportunity_id uuid references public.erp_opportunities(id),sample_id uuid references public.erp_sample_requests(id),kind text not null check(kind in ('call','email','meeting','message','note','follow_up')),subject text not null,notes text not null,due_date date,assignee uuid references public.users(id),state text not null default 'open' check(state in ('open','done','cancelled')),created_by uuid not null references public.users(id),version integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.erp_document_distributions(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.erp_customers(id),document_id uuid not null references public.erp_product_documents(id),document_snapshot jsonb not null,recipient text not null,channel text not null check(channel in ('email','message','portal','other')),sent_date date not null,acknowledged_date date,evidence text not null,state text not null default 'sent' check(state in ('sent','acknowledged','retracted')),created_by uuid not null references public.users(id),version integer not null default 1,created_at timestamptz not null default now());
create or replace function public.work_location_allowed(p_user uuid,p_location uuid,p_verb text default 'read') returns boolean
language sql stable security definer set search_path=pg_catalog,public as $$
 select exists(select from public.erp_locations l join public.erp_warehouses w on w.id=l.warehouse_id where l.id=p_location and (p_verb='read' or (l.active and w.active)) and (
 exists(select from public.users where id=p_user and is_active and role in ('admin qc','administrator inbionusa')) or
 not exists(select from public.erp_warehouse_scopes where user_id=p_user and restricted) or
 exists(select from public.erp_warehouse_access a where a.user_id=p_user and a.warehouse_id=w.id and case p_verb when 'read' then a.can_read when 'write' then a.can_write when 'approve' then a.can_approve else false end)))
$$;
create or replace function public.work_assert_location(p_user uuid,p_location uuid,p_verb text default 'write') returns void language plpgsql security definer set search_path=pg_catalog,public as $$begin
 if p_location is null or not public.work_location_allowed(p_user,p_location,p_verb) then raise insufficient_privilege using message='This warehouse or location is unavailable for your assigned access.';end if;
end $$;
create or replace function public.work_location_sync() returns trigger language plpgsql set search_path=pg_catalog,public as $$begin
 if tg_op='UPDATE' and new.warehouse_id<>old.warehouse_id and (exists(select from public.erp_ledger where location_id=old.id) or exists(select from public.erp_material_ledger where location_id=old.id)) then raise exception using errcode='P0001',message='A location with stock history cannot move to another warehouse. Create a new location and transfer stock.';end if;
 if new.warehouse_id is null then select id into new.warehouse_id from public.erp_warehouses where name=new.warehouse and active;end if;
 select name into new.warehouse from public.erp_warehouses where id=new.warehouse_id;
 if new.warehouse is null then raise exception using errcode='P0001',message='Choose an existing warehouse before saving a location.';end if;return new;
end $$;
drop trigger if exists work_location_sync on public.erp_locations;
create trigger work_location_sync before insert or update on public.erp_locations for each row execute function public.work_location_sync();
create or replace function public.work_material_reserved(p_lot uuid,p_location uuid) returns numeric language sql stable set search_path=pg_catalog,public as $$select coalesce(sum(remaining),0) from public.erp_material_reservations where lot_id=p_lot and location_id=p_location and state='active'$$;
create or replace function public.work_packed(p_kind text,p_lot uuid,p_location uuid) returns numeric language sql stable set search_path=pg_catalog,public as $$select coalesce(sum(c.quantity),0) from public.erp_pallet_contents c join public.erp_pallets p on p.id=c.pallet_id where p.location_id=p_location and p.state='packed' and c.kind=p_kind and coalesce(c.lot_id,c.material_lot_id)=p_lot$$;
create or replace function public.work_material_eligible(p_lot uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$
 select exists(select from public.erp_material_lots l join public.erp_materials m on m.id=l.material_id join public.erp_suppliers s on s.id=l.supplier_id where l.id=p_lot and m.active and s.active and not l.held and (l.expiry_date is null or l.expiry_date>=public.erp_today()) and (not m.requires_qc or l.quality_status='released') and (not m.requires_approved_supplier or exists(select from public.erp_approved_suppliers a where a.material_id=m.id and a.supplier_id=l.supplier_id and a.state='approved' and a.effective_date<=public.erp_today() and (a.expiry_date is null or a.expiry_date>=public.erp_today()))))
$$;
create or replace function public.work_stock_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare actor uuid:=nullif(current_setting('inb.actor',true),'')::uuid;packed numeric;reserved numeric;flow text:=coalesce(current_setting('work.stock_flow',true),'');begin
 if actor is null then return new;end if; -- Direct owner fixtures/maintenance are outside application RPC access.
 perform public.work_assert_location(actor,new.location_id,'write');
 if tg_table_name='erp_material_balances' and exists(select from public.erp_counts where location_id=new.location_id and state in ('counting','submitted')) and flow<>'count' then raise exception using errcode='P0001',message='This location is frozen by a stock count.';end if;
 if tg_op='UPDATE' and new.quantity<old.quantity then
  packed:=public.work_packed(case when tg_table_name='erp_material_balances' then 'material' else 'finished' end,new.lot_id,new.location_id);
  if new.quantity<packed then raise exception using errcode='P0001',message='This quantity is packed on pallets. Select the pallet operation or unpack the required quantity first.';end if;
  if tg_table_name='erp_material_balances' then
   reserved:=public.work_material_reserved(new.lot_id,new.location_id);
   if new.quantity<reserved then raise exception using errcode='P0001',message='This material is reserved for production. Release its reservation before moving or adjusting it.';end if;
   if flow not in ('transfer','supplier_return','disposal','reversal') and not public.work_material_eligible(new.lot_id) then raise exception using errcode='P0001',message='Material is held, expired, awaiting Quality release, or its supplier is not approved.';end if;
  end if;
 end if;return new;
end $$;
drop trigger if exists work_material_stock_guard on public.erp_material_balances;
create trigger work_material_stock_guard before insert or update on public.erp_material_balances for each row execute function public.work_stock_guard();
drop trigger if exists work_finished_stock_guard on public.erp_balances;
create trigger work_finished_stock_guard before insert or update on public.erp_balances for each row execute function public.work_stock_guard();
create or replace function public.work_material_delta(p_transaction uuid,p_lot uuid,p_location uuid,p_quantity numeric) returns void language plpgsql security definer set search_path=pg_catalog,public as $$begin
 if p_quantity=0 then return;end if;
 if exists(select from public.erp_counts where location_id=p_location and state in ('counting','submitted')) then raise exception using errcode='P0001',message='This location is frozen by an active stock count.';end if;
 insert into public.erp_material_balances(lot_id,location_id,quantity) values(p_lot,p_location,0) on conflict do nothing;
 update public.erp_material_balances set quantity=quantity+p_quantity where lot_id=p_lot and location_id=p_location;
 insert into public.erp_material_ledger(transaction_id,lot_id,location_id,delta) values(p_transaction,p_lot,p_location,p_quantity);
end $$;
create or replace function public.work_event(p_entity text,p_id uuid,p_action text,p_actor uuid,p_reason text,p_before jsonb,p_after jsonb) returns void language sql security definer set search_path=pg_catalog,public as $$
 insert into public.erp_work_events(entity,record_id,action,actor_id,reason,before_data,after_data) values(p_entity,p_id,p_action,p_actor,coalesce(p_reason,''),coalesce(p_before,'{}'),coalesce(p_after,'{}'))
$$;
create or replace function public.work_module(p_entity text) returns text language sql immutable as $$select case
 when p_entity in ('warehouses','warehouse_access','warehouse_transfers','pallets','material_inventory','finished_inventory','material_lots','finished_lots','locations') then 'warehouse'
 when p_entity in ('formulas','manufacturing_orders','material_reservations','manufacturing_inputs','manufacturing_outputs','genealogy') then 'production'
 when p_entity in ('material_specs','incoming_inspections','approved_suppliers','deviations','capas') then 'quality'
 when p_entity='controlled_documents' then 'documents'
 when p_entity in ('sample_requests','customer_interactions','document_distributions') then 'crm' else null end$$;
create or replace function public.work_immutable() returns trigger language plpgsql as $$begin raise sqlstate '55000' using message='This operational history is immutable. Record a linked correction.';end $$;
do $$declare t text;begin
 foreach t in array array['erp_work_requests','erp_work_events','erp_manufacturing_inputs','erp_manufacturing_outputs'] loop
 execute format('drop trigger if exists work_immutable on public.%I',t);
 execute format('create trigger work_immutable before update or delete on public.%I for each row execute function public.work_immutable()',t);
 end loop;
 foreach t in array array['erp_warehouses','erp_warehouse_access','erp_warehouse_scopes','erp_work_requests','erp_work_events','erp_approved_suppliers','erp_material_specs','erp_incoming_inspections','erp_controlled_documents','erp_formulas','erp_manufacturing_orders','erp_material_reservations','erp_manufacturing_inputs','erp_manufacturing_outputs','erp_deviations','erp_capas','erp_warehouse_transfers','erp_transfer_lines','erp_pallets','erp_pallet_contents','erp_sample_requests','erp_customer_interactions','erp_document_distributions'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 end loop;
end $$;
-- No new helper is callable through the REST service role.
do $$declare f regprocedure;begin for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'work_%' loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f);end loop;end $$;
notify pgrst,'reload schema';
commit;
